import groovy.json.*
import java.time.*
import java.time.format.DateTimeFormatter
import org.apache.nifi.processor.io.OutputStreamCallback

def flowFile = session.get()
if (!flowFile) return

try {

    def input = new JsonSlurper().parse(session.read(flowFile))
    def output = []

    def istZone = ZoneId.of("Asia/Kolkata")
    def fmt = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")

    input.content.each { item ->
        def ticketId = item.ticketId
        def t = item.ticket

        def createdAtIST = OffsetDateTime.parse(t.createdAt)
                            .atZoneSameInstant(istZone)
                            .format(fmt)

        def updatedAtIST = OffsetDateTime.parse(t.updatedAt)
                            .atZoneSameInstant(istZone)
                            .format(fmt)

        // If escalationInfo is empty, create one row with null key/value
        if (!t.escalationInfo || t.escalationInfo.isEmpty()) {
            output << [
                ticket_id        : ticketId,
                created_by       : t.createdBy,
                updated_by       : t.updatedBy,
                created_at       : createdAtIST,   // yyyy-MM-dd HH:mm:ss IST
                updated_at       : updatedAtIST,    // yyyy-MM-dd HH:mm:ss IST
                escalation_key  : null,
                escalation_value: null
            ]
        } else {
            // Otherwise explode each escalation entry
            t.escalationInfo.each { k, v ->
                output << [
                    ticket_id        : ticketId,
                    created_by       : t.createdBy,
                    updated_by       : t.updatedBy,
                    created_at       : createdAtIST,   // yyyy-MM-dd HH:mm:ss IST
                    updated_at       : updatedAtIST,    // yyyy-MM-dd HH:mm:ss IST
                    escalation_key  : k.toString(),
                    escalation_value: v.toString()
                ]
            }
        }
    }

    flowFile = session.write(flowFile, { out ->
        out.write(JsonOutput.prettyPrint(JsonOutput.toJson(output)).getBytes("UTF-8"))
    } as OutputStreamCallback)

	// Sleep for 5 seconds
	Thread.sleep(5000)

    session.transfer(flowFile, REL_SUCCESS)

} catch (Exception e) {

    // Create failure FlowFile
    def errorFlowFile = session.create(flowFile)

    def errorPayload = [
        error_type : e.getClass().getName(),
        error_message : e.getMessage(),
        processor : "ExecuteScript - Escalation Transform",
        timestamp : new Date().toString()
    ]

    errorFlowFile = session.write(errorFlowFile, { out ->
        out.write(JsonOutput.prettyPrint(JsonOutput.toJson(errorPayload)).getBytes("UTF-8"))
    } as OutputStreamCallback)

    session.transfer(errorFlowFile, REL_FAILURE)
    session.remove(flowFile)
}

import groovy.json.*
import java.time.*
import java.time.format.DateTimeFormatter
import org.apache.nifi.processor.io.OutputStreamCallback

def flowFile = session.get()
if (!flowFile) return

try {

    def input = new JsonSlurper().parse(session.read(flowFile))
    def output = []

    // =========================================================
    // UTC CONFIG
    // =========================================================

    def utcZone = ZoneId.of("UTC")

    def fmt = DateTimeFormatter.ofPattern(
            "yyyy-MM-dd HH:mm:ss"
    )

    // =========================================================
    // PROCESS RECORDS
    // =========================================================

    input.content.each { item ->

        def t = item.ticket

        // =====================================================
        // CREATED AT UTC
        // =====================================================

        def createdAtUTC = null

        if (t.createdAt) {

            createdAtUTC =
                    OffsetDateTime
                            .parse(t.createdAt)
                            .atZoneSameInstant(utcZone)
                            .format(fmt)
        }

        // =====================================================
        // UPDATED AT UTC
        // =====================================================

        def updatedAtUTC = null

        if (t.updatedAt) {

            updatedAtUTC =
                    OffsetDateTime
                            .parse(t.updatedAt)
                            .atZoneSameInstant(utcZone)
                            .format(fmt)
        }

        // =====================================================
        // FINAL OUTPUT
        // =====================================================

        output << [

                ticket_id        : item.ticketId,

                alert_id         : t.alertId,

                rule_id          : t.ruleId,

                priority         : t.priority,

                status           : t.status,

                department       : t.department,

                assignee         : t.assignee,

                location_id      : t.locationId,

                parameter        : t.parameter,

                comment          : t.comment,

                current_level    :
                        (
                                t.currentLevel != null
                                        ? Integer.parseInt(
                                        t.currentLevel.toString()
                                )
                                        : null
                        ),

                sent_notification:
                        (
                                t.sent_notification
                                        ?.toString()
                                        ?.trim()
                                        ? true
                                        : false
                        ),

                created_by       : t.createdBy,

                updated_by       : t.updatedBy,

                created_at       : createdAtUTC,

                updated_at       : updatedAtUTC
        ]
    }

    // =========================================================
    // WRITE OUTPUT
    // =========================================================

    flowFile = session.write(flowFile, { out ->

        out.write(
                JsonOutput.toJson(output)
                        .getBytes("UTF-8")
        )

    } as OutputStreamCallback)

    // =========================================================
    // SUCCESS
    // =========================================================

    session.transfer(flowFile, REL_SUCCESS)

}
catch (Exception e) {

    def errorFlowFile = session.create(flowFile)

    errorFlowFile = session.putAttribute(
            errorFlowFile,
            "error.type",
            e.getClass().getName()
    )

    errorFlowFile = session.putAttribute(
            errorFlowFile,
            "error.message",
            e.getMessage()
    )

    def sw = new StringWriter()

    e.printStackTrace(new PrintWriter(sw))

    errorFlowFile = session.putAttribute(
            errorFlowFile,
            "error.stacktrace",
            sw.toString()
    )

    errorFlowFile = session.write(
            errorFlowFile,
            { out ->

                out.write(
                        JsonOutput.prettyPrint(
                                JsonOutput.toJson([

                                        errorType   :
                                                e.getClass().getName(),

                                        errorMessage:
                                                e.getMessage(),

                                        stackTrace  :
                                                sw.toString()

                                ])
                        ).getBytes("UTF-8")
                )

            } as OutputStreamCallback
    )

    session.transfer(errorFlowFile, REL_FAILURE)

    session.remove(flowFile)
}
